const swampWaterSheet=new Image();swampWaterSheet.assetSrc='assets/swamp-water-spirit-v1.png';
function beginSwampWater(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'crossTide',bespoke:true,windup:.9,origin:{x:e.x,y:e.y},angle,waves:[{at:.9,angle,done:false},{at:1.5,angle:angle+Math.PI/2,done:false}]};}
function swampWaterLaneContains(origin,angle,point){let dx=point.x-origin.x,dy=point.y-origin.y;return Math.abs(dx*Math.cos(angle)+dy*Math.sin(angle))<=360+1e-8&&Math.abs(-dx*Math.sin(angle)+dy*Math.cos(angle))<=24+1e-8;}
const waterAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r3e7')return waterAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;
 e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='crossTide'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=340&&clear)beginSwampWater(e);else{e.state='idle';if(distance>750&&!e.aware)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,70*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,22)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;let a=e.attack;for(let wave of a.waves)if(!wave.done&&e.elapsed>=wave.at){wave.done=true;if(swampWaterLaneContains(a.origin,wave.angle,p)&&lineClear(a.origin,p))hurt(42);playSound('frost',a.origin.x,a.origin.y);}
 if(e.elapsed>=2.3){e.attack=null;e.state='idle';e.t=2.1;}
};
const waterDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r3e7'||!swampWaterSheet.complete||!swampWaterSheet.naturalWidth)return waterDrawBase(e,size);let frame=spriteFrame(e.state,e.anim);if(e.attack?.pattern==='crossTide')frame={row:2,col:e.elapsed<.45?0:e.elapsed<.9?1:e.elapsed<1.7?2:3};let q=project(e.x,e.y),sw=swampWaterSheet.naturalWidth/4,sh=swampWaterSheet.naturalHeight/3,w=110,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,swampWaterSheet,frame.col*sw,frame.row*sh,sw,sh,-w/2,-h*.9,w,h);else ctx.drawImage(swampWaterSheet,frame.col*sw,frame.row*sh,sw,sh,-w/2,-h*.9,w,h);ctx.restore();return true;};
const waterSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r3e7'?95:waterSizeBase(e);
function paintSwampWaterLane(origin,wave,time){let flash=wave.done&&time<wave.at+.18;if(wave.done&&!flash)return;let c=Math.cos(wave.angle),s=Math.sin(wave.angle);ctx.save();ctx.strokeStyle=flash?'#efffff':'#70dce8';ctx.fillStyle=flash?'#8be9f177':'#3c9eac22';ctx.lineWidth=flash?3:2;ctx.beginPath();for(let [i,[along,side]]of [[-360,-24],[360,-24],[360,24],[-360,24]].entries()){let q=project(origin.x+c*along-s*side,origin.y+s*along+c*side);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);}ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}
const waterGroundBase=drawGroundEffects;drawGroundEffects=()=>{waterGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r3e7'):enemies)){if(e.species!=='r3e7'||e.hp<=0||e.attack?.pattern!=='crossTide'||!visibleAt(e.x,e.y))continue;for(let w of e.attack.waves)paintSwampWaterLane(e.attack.origin,w,e.elapsed);}};
